        // atVersion(id) should apply transform too. For the reference contract, if we call atVersion(latest) it
        // must equal currentVersion(). For the mutant which returns raw oracle value in atVersion, these two can differ.

        // Bound oracleVersion to a small range to keep calls meaningful but still fuzzed.
        oracleVersion = bound(oracleVersion, 0, 10);
