        seed = bound(seed, 1, type(uint160).max);

        // We will query currentVersion first; it must succeed on reference and returns transformed price.
        // If latestVersion() == 0 behavior might differ; but currentVersion() reads oracle().currentVersion(), so
        // we just call currentVersion() and atVersion(current.version) and assert equality: for the reference
        // they must be equal; mutant may differ when atVersion omits transform.

        // Call currentVersion
        try c.currentVersion() returns (IOracleProviderMinimal.OracleVersion memory cur) {
            // Now call atVersion with the same version number
            bool ok;
            try c.atVersion(cur.version) returns (IOracleProviderMinimal.OracleVersion memory vAt) {
                // For the correct contract, the two returned structs should match in price (transformed) for same version.
                // We assert equality of the price fields via a single assertTrue reading c (we computed via calls above).
                ok = (vAt.price == cur.price && vAt.version == cur.version && vAt.timestamp == cur.timestamp);
