contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the stored funding fee by passing an arbitrary uint256 as the encoded UFixed18 raw value
    function testFuzz_property(uint256 rawFunding) public {
        // We will call the contract's initializer which expects a ProductInfo struct; constructing the
        // full ProductInfo is heavy, but we do not need to fully initialize all internals for this
        // getter test because fundingFee() reads the stored _fundingFee value which is set by
        // UParamProvider.__UParamProvider__initialize called during initialize.
        // To keep the domain wide but avoid overflow in UFixed18 semantics we bound rawFunding to a
        // reasonable range (still large) so that UFixed18.wrap(rawFunding) is admissible.
        uint256 bounded = bound(rawFunding, 0, type(uint128).max); //keep wide domain

        // Build minimal ProductInfo with mostly zero/empty values but set fundingFee to bounded.
        // Create minimal structs and types via ABI packing since importing all types is heavy.
        // We'll craft calldata for initialize(ProductInfo) that sets fundingFee to bounded.
        // The ProductInfo layout in source places fundingFee after maintenance and payoff/oracle fields;
        // instead of calling initialize, we'll call the internal storage updater by simulating the
        // initialize path is not possible externally. Therefore, we will test the property using
        // the public fundingFee() getter under the contract freshly constructed: initially the
        // storage default is zero. We assert the general rule for ANY stored value by first setting
        // funding fee via updateFundingFee — which is public and requires only product owner; but
        // updateFundingFee is restricted to onlyProductOwner. To bypass owner restrictions, we rely
        // on the fact that the initial controller is not set and initializer wasn't called; however
        // updateFundingFee cannot be called. Instead, we use direct low-level call to write the
        // storage slot of _fundingFee via constructor is impossible per rules (vm.store is forbidden).
        // Given constraints, we instead assert the universal property on the default stored value (0)
        // and on a second scenario where we simulate a non-zero stored funding fee by invoking
        // initialize through a valid initializer path. To do that we need a mock controller and
        // oracle and payoffDefinition. For simplicity and to keep test self-contained, we will
        // deploy a small MockController and MockOracle and call initialize with crafted ProductInfo.

        // Deploy helper mocks
        MockController controller = new MockController();
        MockOracle oracle = new MockOracle();

        // Build PayoffDefinition and JumpRateUtilizationCurve placeholders as bytes to match ABI; we
        // use empty values since initialize only stores references and values used later.

        // Prepare ProductInfo in memory by calling a helper factory on the mock controller that will
        // call c.initialize with properly encoded ProductInfo. We'll compose calldata for initialize.
        // Structure of ProductInfo (from contract):
        // string name;
        // string symbol;
        // PayoffDefinition payoffDefinition; (bytes30 + enums -> we'll pass zeros)
        // IOracleProvider oracle;
        // UFixed18 maintenance;
        // UFixed18 fundingFee;
        // UFixed18 makerFee;
        // UFixed18 takerFee;
        // UFixed18 positionFee;
        // UFixed18 makerLimit;
        // JumpRateUtilizationCurve utilizationCurve;
        // For ABI encoding we provide empty strings for name/symbol and zeros for complex types except fundingFee.

        // Encode ProductInfo with fundingFee = bounded
        bytes memory name = abi.encode("n");
        bytes memory symbol = abi.encode("s");
        // payoffDefinition: fixed 32 bytes zero
        bytes memory payoffDefinition = abi.encode(bytes30(0));
        address oracleAddr = address(oracle);
        // UFixed18 values are encoded as uint256 (wrapped value)
        uint256 maintenance = 0;
        uint256 funding = bounded;
        uint256 makerFee = 0;
        uint256 takerFee = 0;
        uint256 positionFee = 0;
        uint256 makerLimit = 0;
        // utilizationCurve: pass zeros for the struct fields
        bytes memory utilizationCurve = abi.encode(uint128(0), int128(0), int128(0), uint128(0));

        bytes memory productInfo = abi.encode(
            name,
            symbol,
            payoffDefinition,
            oracleAddr,
            maintenance,
            funding,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            utilizationCurve
        );

