        // This is true for the reference implementation for ALL inputs; the mutant that doubles returns 2*funding,
        // so for any funding != 0 the mutant will violate this assertion and the fuzzer can find such input.
        assertTrue(returned.raw == bounded);
    }
}

// Minimal view wrapper types to allow reading return value; this is a tiny helper struct pattern
struct UFixed18View { uint256 raw; }

// Minimal MockController to call initialize on the product and act as controller in __UControllerProvider__initialize
contract MockController {
    function callInitialize(address product, bytes memory productInfo) public {
        // call initialize on product with the provided ABI-encoded ProductInfo
        (bool ok, ) = product.call(abi.encodeWithSignature("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,(uint128,int128,int128,uint128)))",
            // Due to complexity of nested tuple encoding in call, we fallback to low-level assembly of full calldata
            // Instead we directly forward the calldata expecting the test's encoding to match; to keep this minimal,
            // we instead call product.initialize via abi.encodeWithSelector using first 4 bytes of selector and the encoded ProductInfo
            abi.encode(productInfo)
        ));
        // ignore return
        ok;
    }
}

