        // Create a minimal PayoffDefinition bytes30 (we can pass zeroed bytes30 and assume payoffDefinition.valid() returns true in real contract; if not, use zeroed but this test expects initializer to accept it)
        bytes30 zeroPayoff = bytes30(0);

        // Bound taker fee to fit UFixed18 (uint256) and not exceed 1e18*2 to avoid param invalid check in _updateTakerFee
        uint256 boundedTaker = rawTakerFee % (type(uint128).max);

        // Build ABI-encoded ProductInfo; need to match types. For JumpRateUtilizationCurve, pass zeroed struct of 4 numeric fields.
        // Define UFixed18 values as uint256 scaled by 1e18: here we treat boundedTaker as the raw wrapped value already.
        bytes memory name = abi.encode("n");
        bytes memory symbol = abi.encode("s");

        // Prepare ProductInfo via abi.encode with tuple layout
        // types: string,string,tuple(bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,tuple(int128,int128,int128,uint128)
        // We'll pack payoffDefinition as bytes30 inside a tuple to match the struct. For simplicity, use abi.encode with explicit types.
        int128 zeroPackedFixed = int128(0);
        uint128 zeroPackedUFixed = uint128(0);

        bytes memory productInfo = abi.encode(
            "name",
            "symbol",
            // payoffDefinition: emulate PayoffDefinition tuple (uint8 enum values and bytes30) but encode as (bytes30) to match storage expectation loosely
            // to avoid complex mismatch we pack a bytes30 directly where the initialize expects a PayoffDefinition; solidity will accept ABI packing
            zeroPayoff,
            address(oracle),
            uint256(0), // maintenance
            uint256(0), // fundingFee
            uint256(0), // makerFee
            boundedTaker, // takerFee (this is the decisive fuzzed value)
            uint256(0), // positionFee
            uint256(0), // makerLimit
            // utilizationCurve: (int128 minRate, int128 maxRate, int128 targetRate, uint128 targetUtilization)
            zeroPackedFixed,
            zeroPackedFixed,
            zeroPackedFixed,
            zeroPackedUFixed
        );

        // Call initialize on c. The C.initialize signature expects a ProductInfo calldata; we can call it via low-level call with the encoded param.
        // Build function selector for initialize(ProductInfo)
        bytes4 sig = bytes4(keccak256("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"));

        // Compose full calldata: selector + encoded productInfo
        bytes memory data = abi.encodePacked(sig, productInfo);

        // Call initialize as msg.sender = this test contract (which will be treated as controller in __UControllerProvider__initialize validation)
        (bool okInit, ) = address(c).call(data);
        require(okInit, "initialize failed");

        // Now read takerFee via public getter
        // The property: reference contract returns exactly the stored taker fee value (the one we passed); mutant doubles it.
        // We assert equality between takerFee() and the stored raw boundedTaker.

        // Read takerFee from contract
        // c.takerFee() returns UFixed18 (a user-defined type), but ABI will present as uint256; call the function and decode.
        uint256 returned;
        {
            bytes memory ret = address(c).call(abi.encodeWithSelector(bytes4(keccak256("takerFee()"))));
            // low-level call returns (success, data) but call above returns only data; we need to use (success, data) pattern
        }

        (bool succ, bytes memory out) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("takerFee()"))));
        require(succ, "takerFee call failed");
        returned = abi.decode(out, (uint256));

        // Single assertion: returned value equals the stored boundedTaker value
        assertTrue(returned == boundedTaker);
    }
}

