// Note: The SimpleOracle here is a placeholder minimal contract. The test uses only its address when initializing C.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz a stored taker fee (as a uint256 representing the raw UFixed18 value divided by 1e18)
    // The property: after initializing product with that takerFee, calling takerFee() must return the exact stored value.
    // The mutant multiplies stored taker fee by 2, so for many fuzzed non-zero inputs this will fail.
    function testFuzz_property(uint256 rawTakerFee) public {
        // keep the rawTakerFee within a wide but reasonable UFixed18 range [0, type(uint128).max]
        // UFixed18.wrap uses uint256 but many internal packings expect reasonable ranges; keep wide to not exclude bug.
        uint256 bounded = bound(rawTakerFee, 0, type(uint128).max);

        // Build a minimal ProductInfo to call initialize. We need to supply many fields; use zeros/defaults where possible.
        C.ProductInfo memory info;
        info.name = "P";
        info.symbol = "SYM";

        // payoffDefinition: use zeroed bytes30 and default enums (fits in struct)
        // Construct PayoffDefinition via tuple-compatible assignment
        {
            // PayoffDefinition: (PayoffType, PayoffDirection, bytes30)
            // We construct via abi.encode then decode to the struct memory slot.
            bytes memory enc = abi.encode(uint8(0), uint8(0), bytes30(0));
            info.payoffDefinition = abi.decode(enc, (C.PayoffDefinition));
        }

        // For oracle, pass address(0) for now; __UPayoffProvider__initialize checks Address.isContract and will revert unless we bypass initialization path.
        // Instead of calling initialize which performs many checks, we exploit that C inherits many initializers; but the test must remain valid for reference contract.
        // To avoid calling initialize, directly store the taker fee by calling a public function that leads to storing it. There is no direct setter exposed.
        // Alternative approach: use the UParamProvider._update... paths by calling initialize with controller == address(this) and making address(this) appear as contract.

        // Deploy a minimal IController-compatible contract that returns sane defaults and is a contract.
        ControllerMock ctrl = new ControllerMock();

        // Prepare productInfo fields that require contract addresses: oracle and payoffDefinition already set.
        info.oracle = C.IOracleProvider(address(0)); // will be validated inside __UPayoffProvider__initialize, so we must avoid that path

        // Instead of calling C.initialize (which runs many initializers), we will directly manipulate storage via calling initialize and having our ControllerMock be caller
        // Build a valid ProductInfo with a dummy oracle contract that is a contract to satisfy Address.isContract
        OracleMock oracle = new OracleMock();
        info.oracle = C.IOracleProvider(address(oracle));
        info.maintenance = C.UFixed18.wrap(0);
        info.fundingFee = C.UFixed18.wrap(0);
        // Set makerFee to zero
        info.makerFee = C.UFixed18.wrap(0);
        // Here we set takerFee to our fuzzed bounded value (as UFixed18)
        info.takerFee = C.UFixed18.wrap(bounded);
        info.positionFee = C.UFixed18.wrap(0);
        info.makerLimit = C.UFixed18.wrap(type(uint256).max);
        // utilization curve zeroed
        C.JumpRateUtilizationCurve memory curve;
        curve.minRate = C.PackedFixed18.wrap(0);
        curve.maxRate = C.PackedFixed18.wrap(0);
        curve.targetRate = C.PackedFixed18.wrap(0);
        curve.targetUtilization = C.PackedUFixed18.wrap(0);
        info.utilizationCurve = curve;

        // Now call initialize on c but the initializer expects msg.sender to be controller; so call as ctrl which will forward the call
        // Have ctrl call c.initialize with us providing productInfo
        ctrl.callInitialize(address(c), info);

        // Now read back takerFee via the public getter
        C.UFixed18 memory returned = c.takerFee();

        // Also read storage via the public getter maker/taker storage isn't directly exposed; but takerFee() should equal the stored value we set during initialization.
        // The general rule: takerFee() == info.takerFee (the value provided at initialization). We assert that.

        // exactly one assertion that the reference satisfies for all inputs (and mutant breaks for some): equality
        assertTrue(C.UFixed18.unwrap(returned) == C.UFixed18.unwrap(info.takerFee));
    }
}

// Minimal controller mock to satisfy controller() interactions and to invoke initialize as msg.sender
contract ControllerMock {
    function callInitialize(address product, C.ProductInfo memory info) public {
        // forward call as msg.sender to product.initialize
        // use low-level call to preserve msg.sender as this contract
        bytes memory data = abi.encodeWithSelector(C.initialize.selector, info);
        (bool ok, bytes memory res) = product.call(data);
        require(ok, "initialize failed");
    }

    // Stubs to satisfy any calls from product to controller during initialization or uses
    function isProduct(C.IProduct) external pure returns (bool) { return true; }
    function coordinatorFor(C.IProduct) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }
    function paused() external pure returns (bool) { return false; }
    function minFundingFee() external pure returns (C.UFixed18) { return C.UFixed18.wrap(0); }
    function multiInvoker() external pure returns (C.IMultiInvoker) { return C.IMultiInvoker(address(0)); }
    function collateral() external pure returns (C.ICollateral) { return C.ICollateral(address(0)); }
    function incentivizer() external pure returns (C.IIncentivizer) { return C.IIncentivizer(address(0)); }
}

// Minimal oracle mock used to satisfy Address.isContract check and provide trivial oracle versions
contract OracleMock {
    struct OracleVersionRaw { uint256 version; uint256 timestamp; C.Fixed18 price; }
    function sync() external returns (C.IOracleProvider.OracleVersion memory) { C.IOracleProvider.OracleVersion memory v; v.version = 1; v.timestamp = block.timestamp; v.price = C.Fixed18.wrap(0); return v; }
    function currentVersion() external view returns (C.IOracleProvider.OracleVersion memory) { C.IOracleProvider.OracleVersion memory v; v.version = 1; v.timestamp = block.timestamp; v.price = C.Fixed18.wrap(0); return v; }
    function atVersion(uint256) external view returns (C.IOracleProvider.OracleVersion memory) { C.IOracleProvider.OracleVersion memory v; v.version = 1; v.timestamp = block.timestamp; v.price = C.Fixed18.wrap(0); return v; }
}
